const globalConfig = $('Set Global Config').item.json || {};

const parseMessages = (value) => {
  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'string' && value.trim() !== '') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : null;
    } catch {
      return null;
    }
  }

  return null;
};

const normalizeBoolean = (value, fallback) => {
  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (['true', '1', 'yes', 'on'].includes(normalized)) {
      return true;
    }
    if (['false', '0', 'no', 'off'].includes(normalized)) {
      return false;
    }
  }

  if (typeof value === 'number') {
    return value !== 0;
  }

  return fallback;
};

const raw = $json || {};
const rawRoutingProfile = typeof raw.routingProfile === 'string' ? raw.routingProfile.trim().toLowerCase() : '';
const defaultRoutingProfile = typeof globalConfig.defaultRoutingProfile === 'string' && globalConfig.defaultRoutingProfile.trim()
  ? globalConfig.defaultRoutingProfile.trim().toLowerCase()
  : 'standard';
const routingProfile = rawRoutingProfile || defaultRoutingProfile;
const allowedRoutingProfiles = new Set(['low', 'standard', 'high']);
const messages = parseMessages(raw.messages);
const tools = normalizeBoolean(raw.tools, globalConfig.defaultTools === true);
const model = typeof raw.model === 'string' ? raw.model.trim() : '';

let error = '';
if (!messages || messages.length === 0) {
  error = 'Input field messages is required and must be a non-empty array or JSON array string.';
} else if (!allowedRoutingProfiles.has(routingProfile)) {
  error = `Invalid routingProfile ${JSON.stringify(rawRoutingProfile || routingProfile)}. Use low, standard, or high.`;
}

return [{
  json: {
    ...raw,
    messages,
    model,
    routingProfile,
    tools,
    okToSend: !error,
    error
  }
}];

const normalized = $('Normalize input').item.json || {};
const globalConfig = $('Set Global Config').item.json || {};
const routeConfig = $json || {};

const valueOrEmpty = (value) => typeof value === 'string' ? value.trim() : '';
const primaryUrl = valueOrEmpty(routeConfig.primaryUrl);
const fallbackUrl = valueOrEmpty(routeConfig.fallbackUrl);
const fallbackModel = valueOrEmpty(routeConfig.fallbackModel);
const explicitModel = valueOrEmpty(normalized.model);
const primaryModel = explicitModel || valueOrEmpty(routeConfig.primaryModel);
const requestPayload = {};
const excludedKeys = new Set(['okToSend', 'error', 'routingProfile', 'model']);

for (const [key, value] of Object.entries(normalized)) {
  if (excludedKeys.has(key)) {
    continue;
  }

  if (value === undefined || value === '') {
    continue;
  }

  requestPayload[key] = value;
}

requestPayload.model = primaryModel;
requestPayload.messages = normalized.messages;

if (normalized.tools !== true) {
  delete requestPayload.tools;
  delete requestPayload.tool_choice;
}

if (!Array.isArray(requestPayload.tools)) {
  delete requestPayload.tool_choice;
}

const fallbackPayload = {
  ...requestPayload,
  model: fallbackModel
};

let error = '';
if (!primaryUrl) {
  error = 'Primary chat completions URL is required in the route config Set node.';
} else if (!primaryModel) {
  error = 'Primary model is required in the route config Set node or input field model.';
} else if (!fallbackUrl) {
  error = 'Fallback chat completions URL is required in the route config Set node.';
} else if (!fallbackModel) {
  error = 'Fallback model is required in the route config Set node.';
}

return [{
  json: {
    route: normalized.routingProfile,
    primaryUrl,
    primaryModel,
    fallbackUrl,
    fallbackModel,
    telegramErrorRecipient: valueOrEmpty(globalConfig.telegramErrorRecipient),
    primaryRequestBodyJson: JSON.stringify(requestPayload),
    fallbackRequestBodyJson: JSON.stringify(fallbackPayload),
    okToSend: !error,
    error
  }
}];

