const response = $json || {};
const statusCode = Number(response.statusCode || response.code || 0) || null;
const message = [
  response.error,
  response.message,
  response.errcode,
  response.name,
  response.response?.message,
  response.body?.error?.message
].filter(Boolean).map(String).join(' | ');
const lowered = message.toLowerCase();
const hasTransportError = !!response.stack || /timed out|timeout|network|socket|econn|enotfound|dns|connect|unreachable|reset/.test(lowered);
const failedHttp = statusCode !== null && statusCode >= 400;
const retryable = hasTransportError || statusCode === 429 || (statusCode !== null && statusCode >= 500);
const ok = !failedHttp && !hasTransportError && !response.error && !response.errcode;

return [{
  json: {
    ok,
    retryable,
    statusCode,
    failureMessage: message || (failedHttp ? `HTTP ${statusCode}` : 'Unknown error')
  }
}];

